<script setup lang="ts">import {ref,computed} from 'vue';import {Component,Sample,Transformed} from '../types/domain';import {number} from '../utils/format';import DataTable from './common/DataTable.vue';const props=defineProps<{components:Component[];samples:Sample[];transformed?:Transformed[];selected?:number}>();defineEmits<{select:[id:number]}>();const mode=ref<'raw'|'closed'|'replaced'|'clr'>('raw');function setMode(key:string){mode.value=key as 'raw'|'closed'|'replaced'|'clr'}const rows=computed(()=>props.samples.map(s=>{const t=props.transformed?.find(x=>x.sample.id===s.id);return {sample:s,values:t?t[mode.value]:props.components.map(c=>s.values[c.code]),zeros:t?.zero_count??s.zero_count}}));</script><template><section class="composition-matrix"><div class="mode-switch"><button v-for="(label,key) in {raw:'原相对量',closed:'闭合份额',replaced:'零替换后',clr:'CLR坐标'}" :key="key" :disabled="key!=='raw'&&!transformed" :class="{active:mode===key}" @click="setMode(key)">{{label}}</button><span v-if="!transformed">变换由Python在运行后给出</span></div><div class="matrix-scroll"><DataTable :head="['样本 / 组',...components.map(c=>c.label),'零数']"><tr v-for="row in rows" :key="row.sample.id" :class="{selected:row.sample.id===selected}" @click="$emit('select',row.sample.id)"><td><b>{{row.sample.code}}</b><small>{{row.sample.group}}</small></td><td v-for="(v,i) in row.values" :key="i" :class="v===0?'zero':mode==='clr'?(v>0?'positive':'negative'):''">{{number(v,mode==='raw'?3:5)}}</td><td>{{row.zeros}}</td></tr></DataTable></div><p>{{mode==='raw'?'原相对量不比较总规模；闭合后只解释相对关系。':mode==='clr'?'CLR为log(份额)减行内log均值；行和约0，距离为CLR欧氏距离。':'δ以闭合后比例为单位。含零行按显式乘法替换，非零行只闭合。'}}</p></section></template>
